UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
for (int i = 0; i < garage.variants.Length; i++)
{
    var v = garage.variants[i];
    if (v.root == null) continue;
    v.root.SetActive(true);
    float minX = 9999f, maxX = -9999f, minY = 9999f, maxY = -9999f;
    foreach (Renderer r in v.root.GetComponentsInChildren<Renderer>())
    {
        if (!r.gameObject.name.ToLowerInvariant().StartsWith("body")) continue;
        var b = r.localBounds; var c = b.center; var e = b.extents;
        for (int k = 0; k < 8; k++)
        {
            Vector3 lp = new Vector3((k & 1) == 0 ? c.x - e.x : c.x + e.x, (k & 2) == 0 ? c.y - e.y : c.y + e.y, (k & 4) == 0 ? c.z - e.z : c.z + e.z);
            Vector3 cl = garage.transform.InverseTransformPoint(r.transform.TransformPoint(lp));
            if (cl.x < minX) minX = cl.x;
            if (cl.x > maxX) maxX = cl.x;
            if (cl.y < minY) minY = cl.y;
            if (cl.y > maxY) maxY = cl.y;
        }
    }
    sb.AppendLine(garage.specIds[i] + " halfWidth=" + ((maxX - minX) / 2f).ToString("F3") + " xRange=" + minX.ToString("F2") + ".." + maxX.ToString("F2") + " yRange=" + minY.ToString("F2") + ".." + maxY.ToString("F2"));
    v.root.SetActive(i == garage.selected);
}
Debug.Log("PROBE8 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
